import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"conventions.md","filePath":"conventions.md"}`),a={name:`conventions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="conventions" tabindex="-1" dir="auto">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to “Conventions”">​</a></h1><h2 id="naming" tabindex="-1" dir="auto">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to “Naming”">​</a></h2><p dir="auto">One set of naming rules for the whole repo. They bind every contributor and every AI agent that writes code (see <code>AGENTS.md</code>). Identifiers, file names and comments are English; only user-facing UI text is Hebrew.</p><h3 id="principles" tabindex="-1" dir="auto">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to “Principles”">​</a></h3><ol><li dir="auto"><strong>Full, clear names.</strong> Write the whole word. No abbreviation the next reader has to decode (see <a href="#abbreviations">Abbreviations</a>).</li><li dir="auto"><strong>Name the intent, not the implementation.</strong> A name says <em>what</em> a thing is or does for its caller, not <em>how</em> it is built today. A rename should be needed only when the purpose changes, never when the internals do.</li><li dir="auto"><strong>One convention per kind of thing.</strong> The table below is the whole list; if a name does not fit a row, ask before inventing a second style.</li><li dir="auto"><strong>Names are never generic.</strong> <code>data</code>, <code>info</code>, <code>item</code>, <code>temp</code>, <code>result</code>, <code>value</code>, <code>manager</code>, <code>helper</code>, <code>utils</code> and <code>common</code> say nothing. Use them only when the code truly is generic (a type parameter, a generic helper in <code>libs/shared/utils</code>), and never as a file name.</li></ol><table tabindex="0"><thead><tr><th dir="auto">Intent, not implementation</th><th dir="auto">Instead of</th></tr></thead><tbody><tr><td dir="auto"><code>visibleDocs</code></td><td dir="auto"><code>filteredAndSortedArray</code></td></tr><tr><td dir="auto"><code>selectedRoute</code></td><td dir="auto"><code>routeFromUrlMatch</code></td></tr><tr><td dir="auto"><code>sidebarEntries</code></td><td dir="auto"><code>sidebarList</code>, <code>sidebarData</code></td></tr><tr><td dir="auto"><code>loadSpikeMeta()</code></td><td dir="auto"><code>readJsonThenParseMeta()</code></td></tr><tr><td dir="auto"><code>formatPrice(amount)</code></td><td dir="auto"><code>addShekelSignAndRound(n)</code></td></tr><tr><td dir="auto"><code>unreadMessageCount</code></td><td dir="auto"><code>msgCounter</code>, <code>count</code></td></tr></tbody></table><h3 id="casing-at-a-glance" tabindex="-1" dir="auto">Casing at a glance <a class="header-anchor" href="#casing-at-a-glance" aria-label="Permalink to “Casing at a glance”">​</a></h3><table tabindex="0"><thead><tr><th dir="auto">Thing</th><th dir="auto">Convention</th><th dir="auto">Example</th></tr></thead><tbody><tr><td dir="auto">Variables, parameters, object properties</td><td dir="auto">camelCase</td><td dir="auto"><code>selectedRoute</code>, <code>docEntries</code></td></tr><tr><td dir="auto">Functions and methods</td><td dir="auto">camelCase, verb first</td><td dir="auto"><code>buildSidebar</code>, <code>parseRoute</code></td></tr><tr><td dir="auto">Module-level constants</td><td dir="auto">UPPER_SNAKE_CASE</td><td dir="auto"><code>FIRST_PORT</code>, <code>GUIDE_ORDER</code></td></tr><tr><td dir="auto">Types, interfaces, enums, classes</td><td dir="auto">PascalCase</td><td dir="auto"><code>SpikeMeta</code>, <code>ButtonProps</code></td></tr><tr><td dir="auto">React components (the function)</td><td dir="auto">PascalCase</td><td dir="auto"><code>DatePicker</code></td></tr><tr><td dir="auto">Type parameters</td><td dir="auto"><code>T</code>, or <code>T</code> + PascalCase</td><td dir="auto"><code>T</code>, <code>TItem</code>, <code>TKey</code></td></tr><tr><td dir="auto">Files and folders</td><td dir="auto">kebab-case</td><td dir="auto"><code>repo-links.ts</code>, <code>date-picker/</code></td></tr><tr><td dir="auto">React component files (and their <code>.spec</code>/<code>.stories</code>)</td><td dir="auto">PascalCase, see <a href="#files-and-folders">Files</a></td><td dir="auto"><code>DatePicker.tsx</code></td></tr><tr><td dir="auto">CSS custom properties, Tailwind tokens</td><td dir="auto">kebab-case, Tailwind v4 namespaces</td><td dir="auto"><code>--color-brand-500</code></td></tr><tr><td dir="auto">String-literal union members</td><td dir="auto">lowercase, kebab-case if 2+ words</td><td dir="auto"><code>&#39;primary&#39;</code>, <code>&#39;read-only&#39;</code></td></tr></tbody></table><p dir="auto">Acronyms count as words: <code>parseHtml</code>, <code>UrlBuilder</code>, <code>userId</code>, <code>RtlProvider</code>, never <code>parseHTML</code>, <code>URLBuilder</code>, <code>userID</code>.</p><h3 id="variables-and-constants" tabindex="-1" dir="auto">Variables and constants <a class="header-anchor" href="#variables-and-constants" aria-label="Permalink to “Variables and constants”">​</a></h3><ul><li dir="auto">A variable is a noun (or noun phrase) that says what it holds, in the unit or shape that matters: <code>timeoutMilliseconds</code>, <code>priceInAgorot</code>, <code>docsByPath</code>. Collections are plural (<code>routes</code>); a <code>Map</code>/record reads <code>&lt;values&gt;By&lt;Key&gt;</code> (<code>docsByPath</code>).</li><li dir="auto">Do not encode the type in the name (<code>routeArray</code>, <code>strName</code>, <code>userObj</code>).</li><li dir="auto">Lambda and loop parameters are named for what they are, not <code>e</code>, <code>x</code>, <code>item</code>: <code>routes.filter((route) =&gt; route.isPublic)</code>.</li><li dir="auto"><strong>Constants</strong> are module-level <code>const</code> values that never change at runtime: a primitive, a regular expression, a fixed list, a lookup table. They are UPPER_SNAKE_CASE and declared at the top of the module, below the imports. A name that ends in a unit or role says so: <code>REQUEST_TIMEOUT_MILLISECONDS</code>, <code>DEFAULT_PORT</code>.</li><li dir="auto">A <code>const</code> inside a function, or a module-level value that is computed per use or holds behavior (a function, a component, a class), is camelCase / PascalCase like any other variable.</li><li dir="auto">Do not scatter magic numbers or strings. Give a repeated or meaningful literal a constant whose name states what it means (<code>FIRST_PORT</code>, not <code>4200</code>).</li></ul><h3 id="booleans" tabindex="-1" dir="auto">Booleans <a class="header-anchor" href="#booleans" aria-label="Permalink to “Booleans”">​</a></h3><ul><li dir="auto">Start with a state or question verb: <code>is</code>, <code>has</code>, <code>can</code>, <code>should</code>, <code>was</code>, <code>will</code>, or <code>does</code>. Use <code>isActive</code>, <code>hasUnsavedChanges</code>, <code>canSubmit</code>, <code>shouldRetry</code>, <code>wasHandled</code>.</li><li dir="auto">Name the <strong>positive</strong> state: <code>isEnabled</code>, not <code>isNotDisabled</code>. Never use a negation in the name (<code>isNotFound</code>, <code>noItems</code>); invert at the use site (<code>!isVisible</code>). Use a state word instead where the language has one (<code>isEmpty</code>, not <code>hasNoItems</code>).</li><li dir="auto">Never <code>flag</code>, <code>status</code>, <code>check</code> or <code>bool</code> (<code>flag</code>, <code>isOk</code>, <code>checkResult</code>). The name must make <code>if (name)</code> read as a sentence.</li><li dir="auto">Functions that return a boolean follow the same rule (<code>isInternalLink(href)</code>, <code>hasPermission(user)</code>), and read as a question.</li><li dir="auto">Props and options that mirror a native HTML attribute keep the native name (<code>disabled</code>, <code>checked</code>, <code>required</code>) so they can be forwarded unchanged. Our own boolean props use the prefixes above (<code>isLoading</code>, <code>hasError</code>).</li></ul><h3 id="functions" tabindex="-1" dir="auto">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h3><ul><li dir="auto">Name a function with a <strong>verb</strong> (or verb phrase) for what it does for the caller: <code>buildSidebar</code>, <code>loadSpikeMeta</code>, <code>formatPrice</code>, <code>validateEmail</code>.</li><li dir="auto">Prefer a small, consistent vocabulary: <code>get</code> (cheap, synchronous read), <code>load</code>/<code>fetch</code> (I/O), <code>build</code>/<code>create</code> (construct something new), <code>parse</code> / <code>format</code> (text in / text out), <code>to&lt;Target&gt;</code> (convert: <code>toKebabCase</code>), <code>is</code>/<code>has</code>/<code>can</code> (boolean questions), <code>validate</code>, <code>apply</code>, <code>update</code>, <code>remove</code>.</li><li dir="auto">The name describes the <strong>result or purpose</strong>, not the steps. Do not put <code>And</code>/<code>Then</code> in a name: a function that needs one is doing two things, so split it.</li><li dir="auto">No <code>Async</code> suffix, no <code>Fn</code> suffix, no <code>do</code>/<code>process</code>/<code>handle</code> prefixes unless they are the real meaning (see <a href="#event-handlers">Event handlers</a>).</li><li dir="auto">React components are functions named with a PascalCase <strong>noun</strong> (<code>DatePicker</code>, <code>HomePage</code>). Hooks are camelCase starting with <code>use</code> (<code>useDebouncedValue</code>).</li><li dir="auto">A function that is only ever used in one file stays unexported (see <a href="#dead-code">Dead code</a>); its name still follows these rules.</li></ul><h3 id="event-handlers" tabindex="-1" dir="auto">Event handlers <a class="header-anchor" href="#event-handlers" aria-label="Permalink to “Event handlers”">​</a></h3><table tabindex="0"><thead><tr><th dir="auto">Role</th><th dir="auto">Pattern</th><th dir="auto">Example</th></tr></thead><tbody><tr><td dir="auto">Prop that receives a callback (a component&#39;s API)</td><td dir="auto"><code>on</code> + event</td><td dir="auto"><code>onSubmit</code>, <code>onSelectionChange</code></td></tr><tr><td dir="auto">Function inside a component that responds to it</td><td dir="auto"><code>handle</code> + subject + event</td><td dir="auto"><code>handleSearchSubmit</code>, <code>handleRowClick</code></td></tr><tr><td dir="auto">Wiring (one function passed to a prop)</td><td dir="auto">pass the <code>handle*</code> function</td><td dir="auto"><code>&lt;Search onSubmit={handleSearchSubmit} /&gt;</code></td></tr></tbody></table><ul><li dir="auto">A component&#39;s callback props say what <strong>happened</strong> (<code>onSelectionChange</code>), never what the parent will do about it (<code>onUpdateCart</code>).</li><li dir="auto">A <code>handle*</code> function says which element or event it answers, so two on one component stay distinguishable: <code>handleNameChange</code>, <code>handleFormSubmit</code>, not <code>handleChange</code>, <code>handleClick</code>, <code>handler1</code>.</li><li dir="auto">The event parameter is called <code>event</code>, not <code>e</code> or <code>ev</code>.</li><li dir="auto">If a handler only forwards to another function, pass that function directly and skip the wrapper.</li></ul><h3 id="types" tabindex="-1" dir="auto">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h3><ul><li dir="auto"><code>PascalCase</code> for <code>type</code>, <code>interface</code>, <code>enum</code> and class names; a noun describing what the value <strong>is</strong>: <code>SpikeMeta</code>, <code>DocEntry</code>, <code>AppRoute</code>.</li><li dir="auto">No <code>I</code> prefix on interfaces, no <code>Type</code>, <code>Interface</code> or <code>Enum</code> suffix, no <code>Data</code>/<code>Info</code> suffix (<code>UserData</code>, <code>IUser</code>, <code>UserType</code>; write <code>User</code>).</li><li dir="auto">Props of a component: <code>&lt;Component&gt;Props</code> (<code>ButtonProps</code>). Options of a function or tool: <code>&lt;Name&gt;Options</code> (<code>RepoLinkOptions</code>). Generator schemas: <code>&lt;Name&gt;GeneratorSchema</code>. Variants of a closed set: <code>&lt;Component&gt;Variant</code> (<code>ButtonVariant</code>).</li><li dir="auto">Type parameters: <code>T</code> when there is one and its role is obvious; otherwise a <code>T</code>-prefixed descriptive name (<code>TItem</code>, <code>TKey</code>), never <code>U</code>, <code>K</code>, <code>V</code> pairs.</li><li dir="auto">Enums and unions: prefer a string-literal union (<code>&#39;rtl&#39; | &#39;ltr&#39;</code>) to an enum; members are lowercase words, kebab-case if there are two or more.</li><li dir="auto">A type is named in the singular (<code>Route</code>), its collection in the plural variable (<code>routes: Route[]</code>), not <code>RouteArray</code> or <code>RouteList</code>.</li></ul><h3 id="files-and-folders" tabindex="-1" dir="auto">Files and folders <a class="header-anchor" href="#files-and-folders" aria-label="Permalink to “Files and folders”">​</a></h3><ul><li dir="auto"><strong>kebab-case</strong> for every file and folder name: <code>define-app-config.ts</code>, <code>repo-links.ts</code>, <code>docs-source.ts</code>, <code>libs/shared/utils/</code>. Lowercase ASCII, digits and hyphens only; no spaces, underscores or camelCase.</li><li dir="auto">A file is named for the main thing it exports, in kebab-case: <code>define-app-config.ts</code> exports <code>defineAppConfig</code>; <code>use-debounced-value.ts</code> exports <code>useDebouncedValue</code>. Name a file for what it contains (<code>repo-links.ts</code>), never for a role bucket (<code>utils.ts</code>, <code>helpers.ts</code>, <code>common.ts</code>, <code>misc.ts</code>, <code>index2.ts</code>).</li><li dir="auto">Tests and stories sit next to the file and share its stem: <code>repo-links.ts</code> → <code>repo-links.spec.ts</code>; <code>Button.tsx</code> → <code>Button.spec.tsx</code>, <code>Button.stories.tsx</code>.</li><li dir="auto"><strong>Exceptions, and only these:</strong><ul><li dir="auto"><strong>React component files</strong> are PascalCase and match the component name (<code>Button.tsx</code>, <code>HomePage.tsx</code>), as the table below has always said and the <code>pnpm new:component</code> generator produces. The folder holding them is still kebab-case (<code>date-picker/DatePicker.tsx</code>).</li><li dir="auto">Names a tool or platform fixes: <code>README.md</code>, <code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>CODEOWNERS</code>, <code>package.json</code>, <code>tsconfig*.json</code>, <code>vite.config.mts</code>, <code>eslint.config.mjs</code>, <code>index.ts</code> barrels, dotfiles.</li><li dir="auto">Date-led files whose ordering matters: spikes and ADRs (below).</li></ul></li><li dir="auto">Spike slugs and project names are kebab-case; an Nx project name equals its folder name.</li></ul><p dir="auto">Names of specific kinds of files and projects:</p><table tabindex="0"><thead><tr><th dir="auto">Thing</th><th dir="auto">Convention</th><th dir="auto">Example</th></tr></thead><tbody><tr><td dir="auto">Folders, projects</td><td dir="auto">kebab-case; Nx project name = folder name</td><td dir="auto"><code>apps/site</code>, project <code>site</code></td></tr><tr><td dir="auto">Shared util libs</td><td dir="auto"><code>libs/shared/&lt;name&gt;</code>, project <code>shared-&lt;name&gt;</code></td><td dir="auto"><code>libs/shared/utils</code> → <code>shared-utils</code></td></tr><tr><td dir="auto">Other libs</td><td dir="auto"><code>libs/&lt;name&gt;</code></td><td dir="auto"><code>libs/booking</code></td></tr><tr><td dir="auto">Import paths</td><td dir="auto"><code>@starter/&lt;project&gt;</code></td><td dir="auto"><code>@starter/ui</code>, <code>@starter/shared-utils</code></td></tr><tr><td dir="auto">Components</td><td dir="auto">PascalCase file + named export, in a kebab-case folder</td><td dir="auto"><code>src/lib/date-picker/DatePicker.tsx</code></td></tr><tr><td dir="auto">Tests / stories</td><td dir="auto">next to the file: <code>Name.spec.tsx</code>, <code>Name.stories.tsx</code></td><td dir="auto"></td></tr><tr><td dir="auto">Pages</td><td dir="auto"><code>src/pages/&lt;Name&gt;Page.tsx</code></td><td dir="auto"><code>HomePage.tsx</code></td></tr><tr><td dir="auto">Spikes</td><td dir="auto"><code>apps/sandbox/src/spikes/&lt;yyyy-mm&gt;-&lt;slug&gt;/{meta.ts,index.tsx}</code></td><td dir="auto"><code>2026-09-hebrew-fonts</code></td></tr><tr><td dir="auto">ADRs</td><td dir="auto"><code>docs/decisions/NNNN-short-title.md</code></td><td dir="auto"><code>0004-use-zustand.md</code></td></tr></tbody></table><p dir="auto">Prefer named exports. Default exports exist only where a tool requires them (Storybook meta, lazy-loaded spikes).</p><h3 id="abbreviations" tabindex="-1" dir="auto">Abbreviations <a class="header-anchor" href="#abbreviations" aria-label="Permalink to “Abbreviations”">​</a></h3><p dir="auto">Write the full word. <code>configuration</code>, <code>options</code>, <code>response</code>, <code>request</code>, <code>message</code>, <code>button</code>, <code>directory</code>, <code>package</code>, <code>index</code>, <code>error</code>, <code>event</code>, <code>temporary</code> are not shortened to <code>cfg</code>, <code>opts</code>, <code>res</code>, <code>req</code>, <code>msg</code>, <code>btn</code>, <code>dir</code>, <code>pkg</code>, <code>idx</code>, <code>err</code>/<code>e</code>, <code>ev</code>, <code>tmp</code>. Single-letter names are not used for variables or parameters.</p><p dir="auto">The closed list of short forms that <strong>are</strong> allowed, because everyone reading this repo already knows them or an external API fixes them:</p><ul><li dir="auto">Initialisms: <code>id</code>, <code>url</code>, <code>uri</code>, <code>html</code>, <code>css</code>, <code>json</code>, <code>api</code>, <code>ui</code>, <code>ux</code>, <code>e2e</code>, <code>rtl</code>, <code>ltr</code>, <code>adr</code>, <code>ci</code>, <code>cli</code>, <code>ssr</code>, <code>i18n</code>.</li><li dir="auto">Names fixed by the platform or framework: React <code>props</code> and <code>ref</code>, <code>process.env</code>, <code>cwd</code>, the HTML <code>dir</code> and <code>lang</code> attributes.</li><li dir="auto"><code>cn</code>, the class-name joiner exported by <code>@starter/shared-utils</code> (see <code>AGENTS.md</code>).</li></ul><p dir="auto">Adding a short form means adding it to this list in the same change.</p><h3 id="existing-code-and-divergences" tabindex="-1" dir="auto">Existing code and divergences <a class="header-anchor" href="#existing-code-and-divergences" aria-label="Permalink to “Existing code and divergences”">​</a></h3><p dir="auto">These rules apply to <strong>new and changed</strong> code. <code>apps/</code>, <code>libs/</code> and the unprotected <code>tools/</code> were brought into line in one behavior-neutral rename. Protected and pipeline code (<code>.github/</code>, <code>tools/security/</code>, <code>tools/workspace-plugin/</code>, <code>tools/pipeline-map/</code>) was not touched and still contains old names (<code>cfg</code>, <code>opts</code>, <code>dir</code>, <code>e</code>, and <code>.test.mjs</code> / <code>.spec.mjs</code> mixes); do not rename them in an unrelated change. When you touch a line or a file for another reason, bring that line into line with this section. A dedicated rename is its own small, behavior-neutral commit.</p><p dir="auto">Where this section differs from what was already documented:</p><ul><li dir="auto"><strong>Component files stay PascalCase.</strong> The earlier rule (components: PascalCase file, kebab-case folder) is kept as the one named exception to &quot;kebab-case files&quot;. It was not changed to kebab-case because the generators, stories and every existing component already use it.</li><li dir="auto"><strong>Constants</strong> were not previously documented. Code already uses UPPER_SNAKE_CASE for module-level constants (<code>FIRST_PORT</code>, <code>GUIDE_ORDER</code>); this section only writes that down.</li><li dir="auto">Nothing else in the table above or in <code>AGENTS.md</code> (&quot;UI text is Hebrew; code, identifiers, comments and commit messages are English&quot;, the RTL rules) is changed.</li></ul><h2 id="tags-module-boundaries" tabindex="-1" dir="auto">Tags (module boundaries) <a class="header-anchor" href="#tags-module-boundaries" aria-label="Permalink to “Tags (module boundaries)”">​</a></h2><p dir="auto">Every project has one <code>type:*</code> and one <code>scope:*</code> tag in <code>package.json</code> → <code>nx.tags</code>.</p><table tabindex="0"><thead><tr><th dir="auto">Tag</th><th dir="auto">Meaning</th><th dir="auto">May depend on</th></tr></thead><tbody><tr><td dir="auto"><code>type:app</code></td><td dir="auto">deployable app</td><td dir="auto">feature, ui, util</td></tr><tr><td dir="auto"><code>type:e2e</code></td><td dir="auto">Playwright project</td><td dir="auto">util</td></tr><tr><td dir="auto"><code>type:feature</code></td><td dir="auto">React + logic (pages, state, data)</td><td dir="auto">feature, ui, util</td></tr><tr><td dir="auto"><code>type:ui</code></td><td dir="auto">presentational React components</td><td dir="auto">ui, util</td></tr><tr><td dir="auto"><code>type:util</code></td><td dir="auto">framework-free TypeScript</td><td dir="auto">util</td></tr><tr><td dir="auto"><code>type:tooling</code></td><td dir="auto">build/dev tooling (<code>tools/*</code>)</td><td dir="auto">(not imported by app code)</td></tr><tr><td dir="auto"><code>scope:product</code></td><td dir="auto">ships to users</td><td dir="auto">product, shared</td></tr><tr><td dir="auto"><code>scope:dev</code></td><td dir="auto">internal helpers (sandbox, ...)</td><td dir="auto">dev, shared, product</td></tr><tr><td dir="auto"><code>scope:shared</code></td><td dir="auto">usable by everyone</td><td dir="auto">shared</td></tr></tbody></table><p dir="auto">The rules live in the root <code>eslint.config.mjs</code> (<code>@nx/enforce-module-boundaries</code>).</p><h2 id="sandbox-spikes" tabindex="-1" dir="auto">Sandbox spikes <a class="header-anchor" href="#sandbox-spikes" aria-label="Permalink to “Sandbox spikes”">​</a></h2><p dir="auto">A spike answers <strong>one question</strong> quickly and then goes away.</p><table tabindex="0"><thead><tr><th dir="auto">Stage</th><th dir="auto">What happens</th></tr></thead><tbody><tr><td dir="auto">Create</td><td dir="auto"><code>pnpm new:spike &lt;slug&gt;</code> creates <code>src/spikes/&lt;yyyy-mm&gt;-&lt;slug&gt;/meta.ts</code> (title + the question, in <code>description</code>) and <code>index.tsx</code> (the experiment). It appears on the sandbox index automatically. Reusing a slug is an error.</td></tr><tr><td dir="auto">Run</td><td dir="auto"><code>pnpm nx dev sandbox</code> (<a href="http://localhost:4201" target="_blank" rel="noreferrer">http://localhost:4201</a>). Each spike is lazy-loaded in its own chunk; the build fails if one lands in the main chunk.</td></tr><tr><td dir="auto">Verify</td><td dir="auto">Spikes are linted (including the RTL rule), typechecked and built by <code>pnpm verify</code>. They need no tests. A spike that doesn&#39;t compile is fixed or deleted, never excluded.</td></tr><tr><td dir="auto">Promote</td><td dir="auto">The question was answered with &quot;yes&quot;: move the code into a lib or app (<code>pnpm new:lib</code>, <code>pnpm new:component</code>), then delete the spike.</td></tr><tr><td dir="auto">Delete</td><td dir="auto">Remove the folder. Nothing else references it; <code>verify</code> stays green even with zero spikes.</td></tr></tbody></table><p dir="auto">Rules: nothing imports from the sandbox (module boundaries enforce it), and the sandbox is never deployed.</p><p dir="auto">Projects that don&#39;t want a sandbox remove it with <code>pnpm nx g @nx/workspace:remove sandbox</code>. <code>pnpm new:spike</code> then fails with a clear &quot;No sandbox app&quot; message.</p><h2 id="rtl" tabindex="-1" dir="auto">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h2><ul><li dir="auto"><code>dir</code>/<code>lang</code> are set per app in <code>index.html</code>. Libraries never assume a direction.</li><li dir="auto">Logical utilities only. ESLint (<code>no-restricted-syntax</code> in the root config) rejects physical ones: <code>ml/mr/pl/pr/left/right-*</code>, <code>text-left/right</code>, <code>rounded-l/r</code>, <code>border-l/r</code>, <code>float-left/right</code>.</li><li dir="auto">Storybook defaults to RTL; flip the <strong>Direction</strong> toolbar to check LTR.</li><li dir="auto">Two tests guard these rules where ESLint alone does not reach: <code>libs/shared/utils/src/lib/conventions-audit.spec.ts</code> fails if a <code>.css</code> file under <code>libs/</code> or <code>apps/</code> uses a physical property (plain CSS isn&#39;t linted), and exercises the ESLint physical-class regex itself against every family named in its comment, with and without a variant prefix and <code>-</code> negation.</li><li dir="auto">Direction-bearing icons (arrows, chevrons) need <code>rtl:rotate-180</code>.</li></ul><h2 id="styling" tabindex="-1" dir="auto">Styling <a class="header-anchor" href="#styling" aria-label="Permalink to “Styling”">​</a></h2><ul><li dir="auto">Tailwind v4 utilities only; design tokens live in <code>libs/ui/src/styles.css</code> under <code>@theme</code>. No hard-coded hex or <code>rgb()</code>/<code>rgba()</code> colour literal in a <code>libs/ui</code> component — <code>libs/ui/src/conventions-audit.spec.ts</code> scans every <code>.tsx</code> under <code>libs/ui/src</code> and fails on one.</li><li dir="auto">Every component exported from <code>libs/ui/src/index.ts</code> needs a sibling <code>*.spec.tsx</code> and <code>*.stories.tsx</code>; the same spec file&#39;s &quot;component export coverage&quot; block fails on a missing one.</li><li dir="auto">Join conditional classes with <code>cn()</code> from <code>@starter/shared-utils</code>. <code>cn()</code> also accepts a (possibly nested) array or a <code>{ className: condition }</code> object, clsx-style, but it does not merge or dedupe conflicting Tailwind utility classes (<code>cn(&#39;p-2&#39;, &#39;p-4&#39;)</code> keeps both, in call order) — see <code>libs/shared/utils/src/lib/cn.spec.ts</code>.</li></ul><h2 id="dependencies" tabindex="-1" dir="auto">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><ul><li dir="auto">Dependabot opens the update PRs (see <code>.github/dependabot.yml</code>). It bumps <code>nx</code> / <code>@nx/*</code> versions but never runs <code>nx migrate</code>. Nx minors ride in the <code>npm-minor-patch</code> group; majors get their own <code>nx</code> group PR.</li><li dir="auto">For any Nx bump that has migrations (always check majors), don&#39;t merge the Dependabot PR as is. Locally run <code>pnpm nx migrate &lt;version&gt;</code>, <code>pnpm install</code> and <code>pnpm nx migrate --run-migrations</code>, then <code>pnpm verify</code>. Delete <code>migrations.json</code> and open one PR with the result; close the Dependabot PR.</li><li dir="auto">Use the exact syntax from the Nx docs for the installed Nx major; check <code>pnpm nx migrate --help</code> and don&#39;t guess flags.</li></ul><h2 id="dead-code" tabindex="-1" dir="auto">Dead code <a class="header-anchor" href="#dead-code" aria-label="Permalink to “Dead code”">​</a></h2><p dir="auto"><code>knip</code> runs in <code>pnpm verify</code> and CI. Unused files, exports, types and dependencies fail it. Don&#39;t export a symbol just in case; export it when something imports it. If code is used without an import knip can follow (a workflow script, a hook, a generator loaded by Nx), teach knip in <code>knip.ts</code> with an <code>entry</code> and a one-line reason. Don&#39;t ignore a whole folder.</p><h2 id="git" tabindex="-1" dir="auto">Git <a class="header-anchor" href="#git" aria-label="Permalink to “Git”">​</a></h2><ul><li dir="auto">Small commits with an imperative subject line in English (&quot;Add booking form&quot;).</li><li dir="auto"><code>main</code> is always deployable; it deploys to Pages on every push.</li></ul>`,53)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};